import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long fastPower(long base, long exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 1) {
            System.out.println(fastPower(p, p));
            return;
        }

        long[] w = new long[(int) p];
        for (long i = 1; i < p; i++) {
            w[(int) i] = (k * i) % p;
        }

        boolean[] visited = new boolean[(int) p];
        int cycleCount = 0;

        for (int i = 1; i < p; i++) {
            if (visited[i]) continue;
            int t = i;
            while (!visited[t]) {
                visited[t] = true;
                t = (int) w[t];
            }
            cycleCount++;
        }

        System.out.println(fastPower(p, cycleCount));
    }
}
